  13 /// Compute the --check exit code as a raw `u8` from a status report.
  14 ///
  15 /// Returns:
  16 /// - `1` when there are packages with pending changesets (maps to `ExitCode::FAILURE`).
  17 /// - `2` when no changesets are pending (sentinel for CI scripts).
  18 pub(crate) fn check_exit_code_raw(report: &StatusReport) -> u8 {
  19     if report.has_changesets {
  20         1
  21     } else {
  22         2
  23     }
  24 }
  25 
  26 pub fn handle(args: StatusArgs, global: &GlobalArgs) -> Result<ExitCode, CliError> {
