  43         .diagnostics
  44         .iter()
  45         .any(|d| d.severity == DiagnosticSeverity::Error || (args.strict && d.severity == DiagnosticSeverity::Warning));
  46 
  47     if has_errors {
  48         Ok(ExitCode::FAILURE)
  49     } else if args.check {
